import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';

export async function gate({ referenceDir, submissionDir }) {
  const token = crypto.randomBytes(32).toString('hex');
  const id = crypto.randomBytes(8).toString('hex');
  const runnerPath = path.join(referenceDir, 'r-' + id + '.mjs');
  const resultPath = path.join(referenceDir, 'o-' + id + '.json');
  const answerPath = path.join(submissionDir, 'answer.mjs');

  const cases = [];
  const add = (a) => { cases.push(a); };

  add([]);
  add([5]);
  add([1, 2, 3]);
  add([4, 4, 4, 4]);
  add([1, 1, 2, 3]);
  add([1, 2, 3, 3]);
  add([-3, -3, -1, 0, 0, 2]);
  add([7]);
  add([7, 7]);
  add([0]);
  add([-1]);
  add(Array(2).fill(7));
  add(Array(3).fill(7));
  add(Array(11).fill(7));
  add(Array(20).fill(7));
  add(Array(39).fill(7));
  add(Array(40).fill(7));
